"""Writes results/summary_tables.md from the CSVs (no numbers typed by hand). Per fold, never averaged."""
import os, sys, pandas as pd
sys.path.insert(0, os.path.dirname(__file__)); from common4 import *
R = S4 / "results"; A = pd.read_csv(R / "per_fold_auc.csv"); G = pd.read_csv(R / "generalisation_gap.csv"); F = pd.read_csv(S4 / "qc/folds.csv")
L = ["# Stage4 summary tables (generated by scripts/05_tables_md.py)", "",
     "Cell = held-out AUC [95% bootstrap CI] · random median (2.5–97.5%) · proportion of 50 size-matched random panels ≥ curated.",
     "† = derivation/validation overlap with the held-out cohort (optimistic). ‡ = overlap through sub-series containment, added beyond your list.", ""]
L += ["## Folds", "", F[["task", "heldout", "training_cohorts", "n_train", "train_pos", "train_neg", "n_test", "test_pos", "test_neg", "z_reference_samples"]].to_markdown(index=False), ""]
for task in TASKS:
    for m in ["LR", "RF", "MLP", "MLP_alpha", "singscore", "DirAvg"]:
        s = A[(A.task == task) & (A.method == m)].copy()
        s["cell"] = s.apply(lambda r: f"{r.AUC:.3f} [{r.CI_low:.2f}–{r.CI_high:.2f}]" + ("‡" if r.overlap_added_subseries_containment else ("†" if r.optimistic else "")) +
                            f" · {r.rand_median:.2f} ({r.rand_p2_5:.2f}–{r.rand_p97_5:.2f}) · {r.prop_random_ge_curated:.2f}", axis=1)
        L += [f"## {task} — {m}" + (" (alpha by inner LOCO; random reference = random MLP at the same alpha)" if m == "MLP_alpha" else
                                     " (alpha 1e-4; random reference = random MLP at the curated panel's tuned alpha)" if m == "MLP" else ""), "",
              s.pivot(index="heldout", columns="panel", values="cell").to_markdown(), ""]
    g = G[G.task == task].copy(); g["cell"] = g.apply(lambda r: f"{r.train_pooled_AUC:.2f} → {r.heldout_AUC:.2f} ({r.gap_pooled_minus_heldout:+.2f})", axis=1)
    L += [f"## {task} — generalisation gap (pooled training resubstitution AUC → held-out AUC (gap))", "",
          g.pivot_table(index=["heldout", "panel"], columns="method", values="cell", aggfunc="first")[["LR", "RF", "MLP", "MLP_alpha", "singscore", "DirAvg"]].to_markdown(), ""]
    sh = A[(A.task == task) & (A.method == "LR") & (A.panel == "Native")][["heldout", "heldout_allgene_mean_AUC", "heldout_allgene_mean_CI", "heldout_share_genes_dev_gt_0_2", "heldout_quantile_normalised", "zero_filled_in_heldout"]]
    L += [f"## {task} — held-out global shift (all-gene per-sample mean vs class) and Native genes missing from the held-out cohort", "", sh.to_markdown(index=False), ""]
open(R / "summary_tables.md", "w").write("\n".join(L)); print("ok", len(L))
